export const cases=Array.from({length:30},(_,i)=>{
 const fields={'ส่วนราชการ':'หน่วยงานตัวอย่าง','ที่':`ทดสอบ ${i+1}/2569`,'วันที่':'25 ตุลาคม 2569','เรื่อง':'ขอใช้ห้องประชุม','เรียน':'หัวหน้าหน่วยงานตัวอย่าง','เรื่องเดิม':'[รอตรวจสอบ]','ข้อเท็จจริง':`กิจกรรมจำลอง ${i+1} วันที่ 5 พฤศจิกายน 2569\nผู้เข้าร่วม ${i+10} คน เวลา 09.00–12.00 น.`,'ข้อพิจารณา':'ความพร้อมห้อง [รอตรวจสอบ]','ข้อเสนอ':'ขออนุญาตใช้ห้องและประสานผู้ดูแล'};
 if(i>=20)delete fields['ส่วนราชการ'];
 if(i%3===1)fields['ข้อเท็จจริง']=fields['ข้อเท็จจริง'].replace('\n',' ');
 return {id:i+1,fields,input:'จัดทำบันทึกข้อความ\n'+Object.entries(fields).map(([k,v])=>k+(i%3===2?'：':': ')+v).join(i%3===1?' ; ':'\n')};
});